// 固定帧1原图M连续轮廓单角基准：不读真值，不修改任何冻结门限。
// 端点上限按真实轮廓计算；重复100次仅测拟合，不代表完整pipeline资源。
#include "corner_edge_fit.hpp"
#include <opencv2/imgproc.hpp>
#include <fstream>
#include <iostream>
#include <chrono>
#include <algorithm>
#include <set>
int main(){std::ifstream s("src/tushenghao/tests/data/video_fragmented_boundary.txt");std::array<std::array<cv::Point2d,2>,2> e;for(auto& edge:e)for(auto& p:edge)s>>p.x>>p.y;int x,y;std::vector<cv::Point> c;while(s>>x>>y)c.emplace_back(x,y);mark::CornerConfig cfg;cfg.approximation_epsilon_=1;cfg.min_line_points_=10;cfg.max_line_fit_error_=.5;cfg.max_corner_error_=1.5;cfg.observation_budget_=mark::CornerObservationBudget{3,9,4.5,2,13.5,9.5,14};std::vector<cv::Point> poly;cv::approxPolyDP(c,poly,1,true);std::set<size_t> ids;for(auto p:poly){size_t anchor=std::find(c.begin(),c.end(),p)-c.begin();ids.insert(anchor);for(int sign:{-1,1}){size_t last=anchor;double walk=0;for(size_t k=1;k<c.size();++k){size_t j=sign>0?(anchor+k)%c.size():(anchor+c.size()-k)%c.size();walk+=cv::norm(c[j]-c[last]);if(walk>2)break;ids.insert(j);last=j;}}}std::cout<<"simplified_vertices="<<poly.size()<<" endpoint_count="<<ids.size()<<" candidate_upper="<<ids.size()*(ids.size()-1)<<"\n";std::vector<double> times;for(int i=0;i<100;++i){auto t=std::chrono::steady_clock::now();auto r=mark::fitObservedEdgePair(c,e,cfg);times.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count());if(!r.evidence){std::cerr<<r.reason;return 1;}if(i==0){auto& v=*r.evidence;std::cout<<"contour_points="<<c.size()<<" segment_begins="<<v.observed_segment_ids_[0]<<','<<v.observed_segment_ids_[1]<<" segment_ends="<<v.observed_segment_end_ids_[0]<<','<<v.observed_segment_end_ids_[1]<<"\n"<<"mean_line_residuals="<<v.line_mean_residual_px_[0]<<','<<v.line_mean_residual_px_[1]<<" corner_error="<<v.corner_error_px_<<" support_sizes="<<v.original_support_arcs_[0].size()<<','<<v.original_support_arcs_[1].size()<<'\n';}}std::sort(times.begin(),times.end());double sum=0;for(auto t:times)sum+=t;std::cout<<"iterations=100 mean_ms="<<sum/100<<" p99_ms="<<times[98]<<" max_ms="<<times[99]<<'\n';}
